// كاستر ستور — ملف تثبيت واحد. شغّله:  node caster-store-setup.js
// ينشئ مجلد caster-store بكل ملفات المشروع، ثم يولّد ملفات الأصوات.
const fs = require('fs'), path = require('path'), cp = require('child_process');
const FILES = {"app.json": {"t": "{\n  \"expo\": {\n    \"name\": \"كاستر ستور\",\n    \"slug\": \"caster-store\",\n    \"version\": \"1.0.0\",\n    \"orientation\": \"portrait\",\n    \"userInterfaceStyle\": \"automatic\",\n    \"ios\": {\n      \"supportsTablet\": true,\n      \"bundleIdentifier\": \"com.casterstore.app\"\n    },\n    \"android\": {\n      \"package\": \"com.casterstore.app\",\n      \"adaptiveIcon\": {\n        \"foregroundImage\": \"./assets/adaptive-icon.png\",\n        \"backgroundColor\": \"#F5F1E5\"\n      }\n    },\n    \"plugins\": [\n      [\n        \"expo-notifications\",\n        {\n          \"color\": \"#1F3A6E\",\n          \"sounds\": [\n            \"./assets/sounds/chime.wav\",\n            \"./assets/sounds/bell.wav\",\n            \"./assets/sounds/pop.wav\",\n            \"./assets/sounds/ding.wav\",\n            \"./assets/sounds/alert.wav\",\n            \"./assets/sounds/melody.wav\",\n            \"./assets/sounds/soft.wav\",\n            \"./assets/sounds/horn.wav\"\n          ],\n          \"icon\": \"./assets/notification-icon.png\"\n        }\n      ],\n      [\n        \"expo-image-picker\",\n        {\n          \"photosPermission\": \"يحتاج التطبيق للوصول إلى الصور لإرسالها في الدعم أو رفعها للمنتجات.\"\n        }\n      ]\n    ],\n    \"extra\": {\n      \"eas\": {\n        \"projectId\": \"YOUR_EAS_PROJECT_ID\"\n      }\n    },\n    \"icon\": \"./assets/icon.png\",\n    \"splash\": {\n      \"image\": \"./assets/splash.png\",\n      \"resizeMode\": \"contain\",\n      \"backgroundColor\": \"#F5F1E5\"\n    }\n  }\n}"}, "README.md": {"t": "# كاستر ستور — تطبيق متجر (أندرويد / iOS)\n\nتطبيق Expo (React Native) + Supabase. واجهة عربية RTL.\n\n## المزايا\n- **شاشة افتتاحية** متحركة عند فتح التطبيق، ثم الواجهة الرئيسية.\n- **20 قسماً** بلا تكرار: الأكثر مبيعاً، عروض خاصة ومنتجات موسمية، الأجهزة الإلكترونية، الأجهزة الكهربائية والمنزلية، الأثاث المنزلي والديكور، مستلزمات المطبخ، مستحضرات التجميل والعناية، أدوات الحلاقة والعناية الشخصية، مباخر وملطفات الجو، مستلزمات السيارات، الصحة والرياضة، ألعاب وهوايات، ملابس وأكسسوارات، جديد، إنارة وإضاءة، عدد وأدوات، النظارات، كوزمتك، ساعات رجالية، ساعات نسائية.\n- شريط سفلي (من اليمين): **الرئيسية • الأقسام • السلة • طلباتي • الدعم • الإعدادات**.\n- الزائر يتصفح فقط. الشراء والدعم يحتاجان حساباً.\n- **الحساب:** إنشاء بالهاتف (يمين) أو Gmail (يسار) مع تأكيد كلمة المرور، وتحتهما تسجيل الدخول بالبريد أو الهاتف. الحساب محفوظ على الخادم فيمكنك الدخول بعد حذف التطبيق وتثبيته.\n- **الطلب:** السلة (تحديد الكمية) ← إكمال ← الاسم الثلاثي + الهاتف + هاتف اختياري + ملاحظات للمندوب ← إكمال ← المحافظة + المنطقة + أقرب نقطة دالة ← تأكيد الطلب، وينتقل فوراً إلى «طلباتي».\n- **حالات الطلب:** قيد المراجعة ← قيد التغليف ← قيد التوصيل ← تم التوصيل، أو تم الرفض مع سبب يراه الزبون. المالك يغيّرها في أي وقت من تبويب «الطلبات».\n- **الدعم:** محادثة سرية (نص + صور) بين كل مستخدم والمالك. عند المالك يظهر كل من راسله كملف شخصي (مثل ماسنجر) ويدخل محادثته ويرد.\n- **الإشعارات (بصوت):** للمالك عند طلب جديد أو رسالة. للمستخدم عند رد المالك أو تغيير حالة طلبه. والمالك يرسل إعلاناً للجميع. صندوق إشعارات داخل التطبيق (زر 🔔 في الرئيسية).\n- **أصوات الإشعارات:** المالك يختار صوتاً لكل نوع (الإعدادات ← أصوات الإشعارات) ولكل إعلان على حدة.\n- **المنتجات (للمالك):** إضافة/تعديل/حذف، صور وفيديوهات بلا حدّ، وصف طويل، روابط اختيارية، تفعيل/إخفاء، «الأكثر مبيعاً».\n- **توصيل مجاني:** شريط بارز في الرئيسية، ويظهر «مجاني» في السلة. لتفعيل رسوم توصيل غيّر `STORE.deliveryFee` في `src/config.js`.\n- **الاستبدال فقط:** لا يوجد إرجاع. الاستبدال بنفس المنتج عند وجود عيب، **خلال يومين من الاستلام** ولا يمكن في اليوم الثالث (مكتوب في صفحة المنتج وفي شروط الاستخدام).\n- **الإعدادات:** الاسم، تغيير كلمة المرور (تشمل حساب المالك)، **المظهر (تلقائي / فاتح / داكن)**، الإشعارات، الإصدار 1.0.0، شروط الاستخدام، سياسة الخصوصية، فيسبوك، مشاركة، تسجيل الخروج، **حذف الحساب**.\n- **حذف الحساب:** نهائي، ولا يمكن فتح الحساب المحذوف مرة أخرى. تُحذف بيانات الحساب والمحادثات والإشعارات، ويبقى سجل الطلبات للمحاسبة دون ربطه بصاحبه. حساب المالك لا يُحذف.\n\n- **لافتة إشعار فورية:** عند وصول أي إشعار والتطبيق مفتوح تظهر لافتة أعلى الشاشة مع الصوت المختار (تعمل حتى في Expo Go). والتطبيق مغلق يصل إشعار النظام بالصوت (يحتاج نسخة EAS).\n\n- **شعار التطبيق:** أيقونة التطبيق وشاشة البداية وأيقونة الإشعار من شعارك (`assets/`).\n- **أصوات من جهازك:** الإعدادات ← أصوات الإشعارات ← «رفع صوت من الجهاز». تعمل كاملة عند فتح التطبيق؛ والتطبيق مغلق يُستخدم صوت مضمّن بديل لأن النظام يشترط ذلك.\n- **تعديل/حذف الإشعارات المنشورة:** الإعدادات ← لوحة المالك ← «الإشعارات المنشورة».\n- **الضغط على الإشعار** يفتح التطبيق على الشاشة المناسبة حتى لو كان مغلقاً.\n- بعد التحديث: شغّل `schema.sql` مجدداً، ثم `npm install`، وأعد `supabase functions deploy notify`، وأعد بناء EAS.\n\n## الإعداد (مرة واحدة)\n\n### 1) Supabase\n1. أنشئ مشروعاً مجانياً على supabase.com.\n2. SQL Editor ← الصق محتوى `supabase/schema.sql` ← Run.\n3. Authentication ← Providers ← Email ← **عطّل \"Confirm email\"** (ضروري ليعمل الدخول بالهاتف).\n4. Project Settings ← API ← انسخ **Project URL** و **anon key** إلى `src/config.js`.\n5. انشر دالة الإشعارات:\n   ```bash\n   npm i -g supabase\n   supabase login\n   supabase link --project-ref <معرّف-مشروعك>\n   supabase functions deploy notify\n   ```\n\n### 2) حساب المالك (مخفي)\n1. بعد `schema.sql` الصق محتوى `supabase/create-owner.sql` في SQL Editor ← Run.\n2. هذا ينشئ حساب المالك مسبقاً بالبريد `2009OmerMohammed12@gmail.com` وبكلمة المرور التي زوّدتني بها، لكنها محفوظة كـ**بصمة bcrypt** فقط (لا يمكن استخراج كلمة المرور منها).\n3. لا يظهر أي شيء عن المالك داخل التطبيق، والبريد محجوز فلا يستطيع أحد تسجيله، ولا توجد ترقية تلقائية بالبريد.\n4. سجّل الدخول بالبريد وكلمة المرور من شاشة تسجيل الدخول العادية، ثم غيّر كلمة المرور من الإعدادات.\n> كلمة المرور كُتبت في المحادثة، لذا يُنصح بتغييرها فوراً من الإعدادات.\n\n### 3) التشغيل\n```bash\nnpm install\nnpx expo start\n```\nالتصفح والطلبات والدردشة تعمل في **Expo Go**. الإشعارات بأصواتك المخصصة تحتاج نسخة مبنية (الخطوة 4).\n\n### 4) بناء نسخة بالإشعارات والأصوات\n```bash\nnpm i -g eas-cli\neas login\neas init                      # ضع projectId الناتج في app.json ← extra.eas.projectId\neas build -p android --profile preview   # ملف APK للتجربة\n```\n- **أندرويد:** إشعارات Push تحتاج مفتاح Firebase (FCM). أنشئ مشروع Firebase، نزّل `google-services.json`، وأضفه عبر `eas credentials` (راجع توثيق Expo: Push notifications → FCM credentials).\n- **iOS:** يحتاج حساب Apple Developer.\n\n## الأصوات\n`assets/sounds` فيها 8 أصوات + الافتراضي. لإضافة صوت: ضع ملف `.wav`، أضفه في `src/sounds.js` وفي `app.json` (قسم sounds)، ثم أعد البناء. أصوات الإشعارات لا يمكن رفعها أثناء التشغيل لأن النظام يتطلب أن تكون ضمن ملفات التطبيق.\n\n## ملاحظات\n- الدخول بالهاتف يتم داخلياً عبر بريد وهمي (`رقم@phone.casterstore.app`) لتجنب رسوم الرسائل النصية. نتيجة ذلك: لا توجد استعادة كلمة مرور بالرسائل. للبريد الحقيقي يمكن تفعيل الاستعادة لاحقاً.\n- أقصى حجم للملف الواحد في الخطة المجانية لـ Supabase 50MB (فيديوهات قصيرة).\n- شروط الاستخدام والخصوصية في `src/legal.js` نصوص عامة، راجعها وعدّلها قبل النشر.\n- الدفع عند الاستلام فقط. لا توجد بوابة دفع إلكتروني.\n- رسوم التوصيل: `src/config.js` ← `STORE.deliveryFee`.\n"}, "App.js": {"t": "import React, { useEffect, useState } from 'react';\nimport { I18nManager, Text, View } from 'react-native';\nimport * as Notifications from 'expo-notifications';\nimport { StatusBar } from 'expo-status-bar';\nimport { NavigationContainer, createNavigationContainerRef } from '@react-navigation/native';\nimport { createNativeStackNavigator } from '@react-navigation/native-stack';\nimport { createBottomTabNavigator } from '@react-navigation/bottom-tabs';\nimport { SafeAreaProvider } from 'react-native-safe-area-context';\n\nimport ManageNotifications from './src/screens/ManageNotifications';\nimport Splash from './src/screens/Splash';\nimport { ThemeProvider, useTheme } from './src/theme';\nimport { AuthProvider, useAuth } from './src/AuthContext';\nimport { ProductsProvider } from './src/ProductsContext';\nimport { CartProvider, useCart } from './src/CartContext';\nimport { NotifProvider } from './src/NotifContext';\nimport { CATEGORIES } from './src/data';\nimport { COLORS } from './src/config';\nimport { setupChannels } from './src/notifications';\n\nimport Home from './src/screens/Home';\nimport Categories from './src/screens/Categories';\nimport Category from './src/screens/Category';\nimport Product from './src/screens/Product';\nimport Cart from './src/screens/Cart';\nimport Checkout from './src/screens/Checkout';\nimport CheckoutAddress from './src/screens/CheckoutAddress';\nimport Orders from './src/screens/Orders';\nimport Support from './src/screens/Support';\nimport Chat from './src/screens/Chat';\nimport Settings from './src/screens/Settings';\nimport Auth from './src/screens/Auth';\nimport Notifs from './src/screens/Notifications';\nimport Legal from './src/screens/Legal';\nimport ChangePassword from './src/screens/ChangePassword';\nimport SoundSettings from './src/screens/SoundSettings';\nimport Broadcast from './src/screens/Broadcast';\nimport ManageProducts from './src/screens/ManageProducts';\nimport ProductEditor from './src/screens/ProductEditor';\n\n// واجهة عربية من اليمين لليسار\nI18nManager.allowRTL(true);\nI18nManager.forceRTL(true);\n\nconst Stack = createNativeStackNavigator();\nconst Tab = createBottomTabNavigator();\nconst navRef = createNavigationContainerRef();\n\nconst icon = (e) => ({ focused }) => <Text style={{ fontSize: 21, opacity: focused ? 1 : 0.5 }}>{e}</Text>;\n\n// الترتيب من اليمين: الرئيسية، الأقسام، السلة، طلباتي، الدعم، الإعدادات\nfunction Tabs() {\n  useTheme();\n  const { count } = useCart();\n  const { isOwner } = useAuth();\n  return (\n    <Tab.Navigator\n      screenOptions={{\n        headerShown: false,\n        tabBarActiveTintColor: COLORS.primary,\n        tabBarInactiveTintColor: COLORS.muted,\n        tabBarLabelStyle: { fontSize: 11, fontWeight: '700' },\n        tabBarStyle: { height: 62, paddingBottom: 6, paddingTop: 4, backgroundColor: COLORS.card, borderTopColor: COLORS.line },\n      }}\n    >\n      <Tab.Screen name=\"Home\" component={Home} options={{ title: 'الرئيسية', tabBarIcon: icon('🏠') }} />\n      <Tab.Screen name=\"Categories\" component={Categories} options={{ title: 'الأقسام', tabBarIcon: icon('🗂️') }} />\n      <Tab.Screen name=\"Cart\" component={Cart} options={{ title: 'السلة', tabBarIcon: icon('🛒'), tabBarBadge: count > 0 ? count : undefined }} />\n      <Tab.Screen name=\"Orders\" component={Orders} options={{ title: isOwner ? 'الطلبات' : 'طلباتي', tabBarIcon: icon('📦') }} />\n      <Tab.Screen name=\"Support\" component={Support} options={{ title: 'الدعم', tabBarIcon: icon('💬') }} />\n      <Tab.Screen name=\"Settings\" component={Settings} options={{ title: 'الإعدادات', tabBarIcon: icon('⚙️') }} />\n    </Tab.Navigator>\n  );\n}\n\n// الاستماع للإشعارات: الضغط على إشعار يفتح الشاشة المناسبة\nfunction Boot() {\n  useEffect(() => {\n    setupChannels();\n    // الضغط على الإشعار يفتح التطبيق مباشرة على الشاشة المناسبة (حتى لو كان التطبيق مغلقاً تماماً)\n    const open = (res, tries = 0) => {\n      const d = res?.notification?.request?.content?.data || {};\n      if (!navRef.isReady()) { if (tries < 40) setTimeout(() => open(res, tries + 1), 250); return; }\n      if (d.kind === 'new_order' || d.kind === 'order_status') navRef.navigate('Tabs', { screen: 'Orders' });\n      else if (d.kind === 'new_message') navRef.navigate('Tabs', { screen: 'Support' });\n      else navRef.navigate('Notifications');\n    };\n    Notifications.getLastNotificationResponseAsync().then((r) => { if (r) open(r); }).catch(() => {});\n    const sub = Notifications.addNotificationResponseReceivedListener((r) => open(r));\n    return () => sub.remove();\n  }, []);\n  return null;\n}\n\nfunction Root() {\n  const { scheme } = useTheme();\n  const navTheme = {\n    dark: scheme === 'dark',\n    colors: {\n      primary: COLORS.primary,\n      background: COLORS.bg,\n      card: COLORS.card,\n      text: COLORS.dark,\n      border: COLORS.line,\n      notification: COLORS.danger,\n    },\n  };\n  return (\n    <NavigationContainer ref={navRef} theme={navTheme}>\n      <StatusBar style={scheme === 'dark' ? 'light' : 'dark'} />\n      <Boot />\n      <Stack.Navigator\n        screenOptions={{\n          headerTitleAlign: 'center',\n          headerTintColor: COLORS.primary,\n          headerStyle: { backgroundColor: COLORS.card },\n          headerTitleStyle: { color: COLORS.dark },\n          headerBackTitleVisible: false,\n          contentStyle: { backgroundColor: COLORS.bg },\n        }}\n      >\n        <Stack.Screen name=\"Tabs\" component={Tabs} options={{ headerShown: false }} />\n        <Stack.Screen name=\"Category\" component={Category} options={({ route }) => ({ title: CATEGORIES.find((c) => c.id === route.params.id)?.name })} />\n        <Stack.Screen name=\"Product\" component={Product} options={{ title: 'تفاصيل المنتج' }} />\n        <Stack.Screen name=\"Checkout\" component={Checkout} options={{ title: 'إتمام الطلب' }} />\n        <Stack.Screen name=\"CheckoutAddress\" component={CheckoutAddress} options={{ title: 'عنوان التوصيل' }} />\n        <Stack.Screen name=\"Chat\" component={Chat} options={({ route }) => ({ title: route.params?.title || 'محادثة' })} />\n        <Stack.Screen name=\"Auth\" component={Auth} options={{ title: 'الحساب' }} />\n        <Stack.Screen name=\"Notifications\" component={Notifs} options={{ title: 'الإشعارات' }} />\n        <Stack.Screen name=\"Legal\" component={Legal} options={({ route }) => ({ title: route.params.kind === 'terms' ? 'شروط الاستخدام' : 'سياسة الخصوصية' })} />\n        <Stack.Screen name=\"ChangePassword\" component={ChangePassword} options={{ title: 'تغيير كلمة المرور' }} />\n        <Stack.Screen name=\"SoundSettings\" component={SoundSettings} options={{ title: 'أصوات الإشعارات' }} />\n        <Stack.Screen name=\"Broadcast\" component={Broadcast} options={{ title: 'إرسال إشعار للجميع' }} />\n        <Stack.Screen name=\"ManageNotifications\" component={ManageNotifications} options={{ title: 'الإشعارات المنشورة' }} />\n        <Stack.Screen name=\"ManageProducts\" component={ManageProducts} options={{ title: 'إدارة المنتجات' }} />\n        <Stack.Screen name=\"ProductEditor\" component={ProductEditor} options={{ title: 'المنتج' }} />\n      </Stack.Navigator>\n    </NavigationContainer>\n  );\n}\n\nfunction SplashGate() {\n  const [done, setDone] = useState(false);\n  return done ? null : <Splash onDone={() => setDone(true)} />;\n}\n\nexport default function App() {\n  return (\n    <SafeAreaProvider>\n      <ThemeProvider>\n        <AuthProvider>\n          <ProductsProvider>\n            <CartProvider>\n              <NotifProvider>\n                <Root />\n                <SplashGate />\n              </NotifProvider>\n            </CartProvider>\n          </ProductsProvider>\n        </AuthProvider>\n      </ThemeProvider>\n    </SafeAreaProvider>\n  );\n}\n"}, "package.json": {"t": "{\n  \"name\": \"caster-store\",\n  \"version\": \"1.0.0\",\n  \"main\": \"node_modules/expo/AppEntry.js\",\n  \"scripts\": {\n    \"start\": \"expo start\",\n    \"android\": \"expo start --android\",\n    \"ios\": \"expo start --ios\",\n    \"sounds\": \"node tools/gen-sounds.js\"\n  },\n  \"dependencies\": {\n    \"@react-native-async-storage/async-storage\": \"1.23.1\",\n    \"@react-navigation/bottom-tabs\": \"^6.6.1\",\n    \"@react-navigation/native\": \"^6.1.18\",\n    \"@react-navigation/native-stack\": \"^6.11.0\",\n    \"@supabase/supabase-js\": \"^2.45.0\",\n    \"expo\": \"~51.0.0\",\n    \"expo-av\": \"~14.0.7\",\n    \"expo-constants\": \"~16.0.2\",\n    \"expo-device\": \"~6.0.2\",\n    \"expo-document-picker\": \"~12.0.2\",\n    \"expo-image-picker\": \"~15.0.7\",\n    \"expo-notifications\": \"~0.28.19\",\n    \"expo-status-bar\": \"~1.12.1\",\n    \"react\": \"18.2.0\",\n    \"react-native\": \"0.74.5\",\n    \"react-native-safe-area-context\": \"4.10.5\",\n    \"react-native-screens\": \"3.31.1\",\n    \"react-native-url-polyfill\": \"^2.0.0\"\n  }\n}\n"}, "eas.json": {"t": "{\n  \"cli\": { \"version\": \">= 10.0.0\" },\n  \"build\": {\n    \"preview\": { \"distribution\": \"internal\", \"android\": { \"buildType\": \"apk\" } },\n    \"production\": {}\n  }\n}\n"}, "src/ui.js": {"t": "import React from 'react';\nimport { View, Text, TextInput, TouchableOpacity, ActivityIndicator, StyleSheet } from 'react-native';\nimport { themed } from './theme';\nimport { COLORS } from './config';\n\nexport function Btn({ title, onPress, kind = 'primary', loading, disabled, style }) {\n  const ghost = kind === 'ghost';\n  const danger = kind === 'danger';\n  return (\n    <TouchableOpacity\n      activeOpacity={0.85}\n      disabled={disabled || loading}\n      onPress={onPress}\n      style={[\n        s.btn,\n        ghost && { backgroundColor: 'transparent', borderWidth: 1.5, borderColor: COLORS.primary },\n        danger && { backgroundColor: COLORS.danger },\n        (disabled || loading) && { opacity: 0.6 },\n        style,\n      ]}\n    >\n      {loading ? (\n        <ActivityIndicator color={ghost ? COLORS.primary : COLORS.onPrimary} />\n      ) : (\n        <Text style={[s.btnTxt, ghost && { color: COLORS.primary }]}>{title}</Text>\n      )}\n    </TouchableOpacity>\n  );\n}\n\nexport function Field({ label, multiline, style, ...p }) {\n  return (\n    <View style={{ marginBottom: 12 }}>\n      {label ? <Text style={s.label}>{label}</Text> : null}\n      <TextInput\n        placeholderTextColor={COLORS.muted}\n        textAlign=\"right\"\n        multiline={multiline}\n        {...p}\n        style={[s.input, multiline && { minHeight: 90, textAlignVertical: 'top' }, style]}\n      />\n    </View>\n  );\n}\n\nexport function Chip({ label, on, onPress, color }) {\n  return (\n    <TouchableOpacity onPress={onPress} style={[s.chip, on && { backgroundColor: color || COLORS.primary, borderColor: color || COLORS.primary }]}>\n      <Text style={[s.chipTxt, on && { color: COLORS.onPrimary }]}>{label}</Text>\n    </TouchableOpacity>\n  );\n}\n\nexport function Empty({ icon = '🛒', text, action, onAction }) {\n  return (\n    <View style={s.empty}>\n      <Text style={{ fontSize: 54 }}>{icon}</Text>\n      <Text style={s.emptyTxt}>{text}</Text>\n      {action ? <Btn title={action} onPress={onAction} style={{ marginTop: 14, paddingHorizontal: 26 }} /> : null}\n    </View>\n  );\n}\n\nexport function Avatar({ name = '?', size = 46 }) {\n  const colors = ['#6C3FE0', '#1D6FB8', '#1E8E5A', '#C2410C', '#B7287A', '#0F766E'];\n  const c = colors[(name.charCodeAt(0) || 0) % colors.length];\n  return (\n    <View style={{ width: size, height: size, borderRadius: size / 2, backgroundColor: c, alignItems: 'center', justifyContent: 'center' }}>\n      <Text style={{ color: '#fff', fontWeight: '800', fontSize: size * 0.42 }}>{name.trim().charAt(0).toUpperCase()}</Text>\n    </View>\n  );\n}\n\nconst s = themed(() => ({\n  btn: { backgroundColor: COLORS.primary, borderRadius: 12, paddingVertical: 14, alignItems: 'center', justifyContent: 'center' },\n  btnTxt: { color: COLORS.onPrimary, fontWeight: '800', fontSize: 15 },\n  label: { textAlign: 'right', color: COLORS.dark, fontWeight: '600', marginBottom: 6 },\n  input: { backgroundColor: COLORS.card, borderRadius: 12, borderWidth: 1, borderColor: COLORS.line, padding: 12, fontSize: 15, color: COLORS.dark },\n  chip: { backgroundColor: COLORS.card, borderRadius: 18, borderWidth: 1, borderColor: COLORS.line, paddingHorizontal: 13, paddingVertical: 7 },\n  chipTxt: { color: COLORS.dark, fontSize: 13 },\n  empty: { alignItems: 'center', justifyContent: 'center', padding: 40 },\n  emptyTxt: { color: COLORS.muted, MaterialApp(
  title: 'My App',
  theme: ThemeData(
    primarySwatch: Colors.blue,
  ),
  home: const MyHomePage(),
)